const H_MAPPING_REGISTRY:
  Readonly<Record<string, Readonly<Record<string, string>>>> =
    H_EXECUTION_DATA.mappingRegistry;

const H_CONTEXTUAL_RENDERING_REGISTRY:
  Readonly<Record<string, {
    readonly input: string;
    readonly unicodeBraille: string;
    readonly source: string;
    readonly category: unknown;
    readonly ruleRefs: readonly unknown[];
  }>> =
    H_EXECUTION_DATA.contextualRenderingRegistry;

const H_DECISION_REGISTRY:
  Readonly<Record<string, GermanKurzschriftDecisionCase>> =
    H_EXECUTION_DATA.decisionRegistry;

const H_CONTROL_REGISTRY:
  Readonly<Record<string, GermanKurzschriftControlCase>> =
    H_EXECUTION_DATA.controlRegistry;

const H_STRUCTURED_REGISTRY:
  Readonly<Record<string, {
    readonly source: string;
    readonly record: unknown;
  }>> =
    H_EXECUTION_DATA.structuredRegistry;

function normalizeKurzKey(key: string): string {
  return key.normalize("NFC").toLocaleUpperCase("de-DE");
}

export function getGermanKurzschriftMapping(
  family: GermanKurzschriftMappingFamily,
  keyInput: string,
): GermanKurzschriftMappingResult {
  const familyMap = H_MAPPING_REGISTRY[family];
  const key = normalizeKurzKey(keyInput);

  if (familyMap === undefined) {
    return Object.freeze({
      ok: false,
      family,
      key,
      code: "UNKNOWN_MAPPING_FAMILY",
    });
  }

  const unicodeBraille = familyMap[key];

  if (unicodeBraille === undefined) {
    return Object.freeze({
      ok: false,
      family,
      key,
      code: "UNKNOWN_MAPPING",
    });
  }

  return Object.freeze({
    ok: true,
    family,
    key,
    unicodeBraille,
  });
}

export function getGermanKurzschriftSourceRendering(
  validationId: string,
  input: string,
): GermanKurzschriftSourceRenderingResult {
  const record = H_CONTEXTUAL_RENDERING_REGISTRY[validationId];

  if (record === undefined) {
    return Object.freeze({
      ok: false,
      validationId,
      input,
      code: "UNKNOWN_SOURCE_RENDERING",
    });
  }

  if (input.normalize("NFC") !== record.input.normalize("NFC")) {
    return Object.freeze({
      ok: false,
      validationId,
      input,
      code: "SOURCE_INPUT_MISMATCH",
    });
  }

  return Object.freeze({
    ok: true,
    validationId,
    input,
    unicodeBraille: record.unicodeBraille,
  });
}

export function getGermanKurzschriftSourceDecisionCase(
  validationId: string,
): GermanKurzschriftDecisionCase | null {
  return H_DECISION_REGISTRY[validationId] ?? null;
}

export function getGermanKurzschriftControlCase(
  validationId: string,
): GermanKurzschriftControlCase | null {
  return H_CONTROL_REGISTRY[validationId] ?? null;
}

export function getGermanKurzschriftStructuredCase(
  validationId: string,
): unknown | null {
  return H_STRUCTURED_REGISTRY[validationId]?.record ?? null;
}

export function executeGermanKurzschriftResolvedPlan(
  segments: readonly GermanKurzschriftResolvedPlanSegment[],
): GermanKurzschriftResolvedExecutionResult {
  const output: string[] = [];

  for (let index = 0; index < segments.length; index += 1) {
    const segment = segments[index]!;

    if (segment.kind === "basisschrift") {
      const result = translateGermanBasisschrift(segment.text);

      if (!result.ok) {
        return Object.freeze({
          ok: false,
          code: "BASISSCHRIFT_FAILURE",
          segmentIndex: index,
          message: "Basisschrift parent execution failed.",
        });
      }

      output.push(result.unicodeBraille);
      continue;
    }

    if (segment.kind === "vollschrift") {
      const result =
        translateGermanVollschriftResolved(
          segment.text,
          segment.resolvedCandidates,
        );

      if (!result.ok) {
        return Object.freeze({
          ok: false,
          code: "VOLLSCHRIFT_FAILURE",
          segmentIndex: index,
          message: "Vollschrift parent execution failed.",
        });
      }

      output.push(result.unicodeBraille);
      continue;
    }

    if (segment.kind === "mapping") {
      const result =
        getGermanKurzschriftMapping(
          segment.family,
          segment.key,
        );

      if (!result.ok) {
        return Object.freeze({
          ok: false,
          code: "MAPPING_FAILURE",
          segmentIndex: index,
          message: "Source-backed Kurzschrift mapping resolution failed.",
        });
      }

      output.push(result.unicodeBraille);
      continue;
    }

    if (segment.kind === "sourceRendering") {
      const result =
        getGermanKurzschriftSourceRendering(
          segment.validationId,
          segment.input,
        );

      if (!result.ok) {
        return Object.freeze({
          ok: false,
          code: "SOURCE_RENDERING_FAILURE",
          segmentIndex: index,
          message: "Source-backed contextual rendering resolution failed.",
        });
      }

      output.push(result.unicodeBraille);
      continue;
    }

    const control =
      getGermanKurzschriftControlCase(
        segment.validationId,
      );

    if (control === null) {
      return Object.freeze({
        ok: false,
        code: "CONTROL_FAILURE",
        segmentIndex: index,
        message: "Unknown source-backed Kurzschrift control case.",
      });
    }

    const value = control[segment.field];

    if (typeof value !== "string") {
      return Object.freeze({
        ok: false,
        code: "CONTROL_FAILURE",
        segmentIndex: index,
        message: "Requested Kurzschrift control field is not materialized.",
      });
    }

    output.push(value);
  }

  const unicodeBraille = output.join("");

  return Object.freeze({
    ok: true,
    unicodeBraille,
    cells: Object.freeze(Array.from(unicodeBraille)),
    segmentCount: segments.length,
    runtime: Object.freeze({
      language: "de",
      mode: "kurzschrift",
      executable: true,
      resolutionBoundary:
        "EXPLICIT_RESOLVED_PLAN_REQUIRED",
      runtimeRegistered: false,
    }),
  });
}
